13	pub struct CargoToml {
14	    path: PathBuf,
15	    absolute: PathBuf,
16	    workspace_root: PathBuf,
17	    role: ManifestRole,
18	    document: toml_edit::DocumentMut,
19	    inherited_version: bool,
20	    inheritance: Option<Arc<WorkspaceInheritance>>,
21	    fingerprint: crate::common::FormatFingerprint,
