77	/// What has been learned about workspace manifests while reading many packages, so each one is parsed once however many
78	/// packages ask about it.
79	#[derive(Debug, Default)]
80	pub struct WorkspaceReads {
81	    declares: HashMap<PathBuf, bool>,
82	    versions: HashMap<PathBuf, Option<Version>>,
83	}
84	
85	impl WorkspaceReads {
86	    /// The workspace-relative `Cargo.toml` of the Cargo workspace that governs the package at `manifest`, found the way
87	    /// Cargo finds it: the directory named by `package.workspace`, else the nearest manifest at or above the package's
88	    /// directory that has a `workspace` table. The search stops at the workspace root. `doc` is the package's own
89	    /// manifest and `manifest_at` supplies any other workspace-relative manifest's text, or `None` when there is none,
90	    /// so a past commit can answer as well as the working tree.
91	    ///
92	    /// # Errors
93	    ///
94	    /// A manifest on the way up that cannot be read or parsed (skipping it could settle on a different root), or a
95	    /// `package.workspace` that leaves the workspace root or names a manifest with no `workspace` table.
96	    pub fn enclosing<E: From<ManifestError>>(
97	        &mut self,
98	        manifest: &Path,
99	        doc: &toml_edit::DocumentMut,
100	        mut manifest_at: impl FnMut(&Path) -> Result<Option<String>, E>,
101	    ) -> Result<Option<PathBuf>, E> {
102	        let dir = manifest.parent().unwrap_or(Path::new(""));
103	        let read_error = |path: &Path, message: String| ManifestError::Read {
104	            path: path.to_path_buf(),
105	            message,
106	        };
107	
108	        if let Some(named) = doc
109	            .get("package")
110	            .and_then(|package| package.get("workspace"))
111	            .and_then(toml_edit::Item::as_str)
112	        {
113	            let root_manifest = workspace_relative(dir.join(named))
114	                .map_err(|error| {
115	                    read_error(
116	                        manifest,
117	                        format!("`package.workspace = \"{named}\"` is unusable: {error}"),
118	                    )
119	                })?
120	                .join("Cargo.toml");
121	            return if self.declares(&root_manifest, &mut manifest_at)? {
122	                Ok(Some(root_manifest))
123	            } else {
124	                Err(read_error(
125	                    manifest,
126	                    format!(
127	                        "`package.workspace = \"{named}\"` names `{}`, which declares no `[workspace]`",
128	                        root_manifest.display()
129	                    ),
130	                )
131	                .into())
132	            };
133	        }
134	
135	        for candidate in dir.ancestors() {
136	            let candidate_manifest = candidate.join("Cargo.toml");
137	            let declares_workspace = if candidate == dir {
138	                declares_workspace(doc)
139	            } else {
140	                self.declares(&candidate_manifest, &mut manifest_at)?
141	            };
142	            if declares_workspace {
143	                return Ok(Some(candidate_manifest));
144	            }
145	        }
146	        Ok(None)
147	    }
148	
149	    /// The `[workspace.package]` version of the workspace manifest `root_manifest`, or `None` when it declares none.
150	    ///
151	    /// # Errors
152	    ///
153	    /// `root_manifest` is missing, cannot be parsed, or declares an invalid version; or `manifest_at` fails.
154	    pub fn version<E: From<ManifestError>>(
155	        &mut self,
156	        root_manifest: &Path,
157	        mut manifest_at: impl FnMut(&Path) -> Result<Option<String>, E>,
158	    ) -> Result<Option<Version>, E> {
159	        if let Some(known) = self.versions.get(root_manifest) {
160	            return Ok(known.clone());
161	        }
162	        let text = manifest_at(root_manifest)?.ok_or_else(|| ManifestError::Read {
163	            path: root_manifest.to_path_buf(),
164	            message: "No such file or directory".to_string(),
165	        })?;
166	        let version = workspace_version_from_source(&text, root_manifest)?;
167	        self.versions.insert(root_manifest.to_path_buf(), version.clone());
168	        Ok(version)
169	    }
170	
171	    fn declares<E: From<ManifestError>>(
172	        &mut self,
173	        manifest: &Path,
174	        manifest_at: &mut impl FnMut(&Path) -> Result<Option<String>, E>,
175	    ) -> Result<bool, E> {
176	        if let Some(known) = self.declares.get(manifest) {
177	            return Ok(*known);
178	        }
179	        let declared = match manifest_at(manifest)? {
180	            Some(text) => declares_workspace(&parse_manifest(manifest, &text)?),
181	            None => false,
182	        };
183	        self.declares.insert(manifest.to_path_buf(), declared);
184	        Ok(declared)
185	    }
186	}
