188	/// Reads workspace-relative manifest text from the working tree under `workspace_root`; `None` when there is none.
189	pub fn read_manifest_text(workspace_root: &Path) -> impl FnMut(&Path) -> Result<Option<String>, ManifestError> + '_ {
190	    move |manifest| {
191	        callisto_model::strict_fs::read_optional(&workspace_root.join(manifest)).map_err(|error| ManifestError::Read {
192	            path: manifest.to_path_buf(),
193	            message: error.to_string(),
194	        })
195	    }
196	}
