208	/// The workspace-relative `Cargo.toml` of the Cargo workspace the package at `manifest` belongs to, read from the working
209	/// tree. A package that no workspace governs is a workspace of its own, which is where its `Cargo.lock` is written.
210	///
211	/// # Errors
212	///
213	/// A manifest on the way up that cannot be read or parsed, or an unusable `package.workspace`.
214	pub fn cargo_workspace_of(
215	    reads: &mut WorkspaceReads,
216	    workspace_root: &Path,
217	    manifest: &Path,
218	) -> Result<PathBuf, ManifestError> {
219	    let manifest = &workspace_relative(manifest).map_err(|error| ManifestError::Read {
220	        path: manifest.to_path_buf(),
221	        message: error.to_string(),
222	    })?;
223	    let text = read_manifest_text(workspace_root)(manifest)?.ok_or_else(|| ManifestError::Read {
224	        path: manifest.to_path_buf(),
225	        message: "No such file or directory".to_string(),
226	    })?;
227	    let doc = parse_manifest(manifest, &text)?;
228	    Ok(reads
229	        .enclosing(manifest, &doc, read_manifest_text(workspace_root))?
230	        .unwrap_or_else(|| manifest.to_path_buf()))
231	}
