272	/// Whether the manifest declares a workspace. Cargo treats any `workspace` table as one, however it is spelled: a
273	/// `[workspace]` header, an inline table, dotted keys, or one that exists only as `[workspace.package]`.
274	pub fn declares_workspace(doc: &toml_edit::DocumentMut) -> bool {
275	    doc.get("workspace").is_some_and(toml_edit::Item::is_table_like)
276	}
