278	/// Parses the text of the `Cargo.toml` at `manifest`, which is used only to name it in the error.
279	pub fn parse_manifest(manifest: &Path, text: &str) -> Result<toml_edit::DocumentMut, ManifestError> {
280	    text.strip_prefix('\u{FEFF}')
281	        .unwrap_or(text)
282	        .parse::<toml_edit::DocumentMut>()
283	        .map_err(|error| ManifestError::Parse {
284	            path: manifest.to_path_buf(),
285	            format: ManifestFormat::CargoToml,
286	            message: error.to_string(),
287	        })
288	}
