290	/// Extracts `[package].name` from an already-parsed `Cargo.toml` document.
291	/// Pure and I/O-free -- operates on a document the caller already has,
292	/// whether that's a fully-opened [`CargoToml`] (via [`Manifest::package_name`])
293	/// or a bare parse a caller made for some other purpose entirely (e.g.
294	/// [`crate::read_identity`], which needs only a package name and deliberately
295	/// does not go through the full [`CargoToml::open`] lifecycle).
296	pub fn cargo_package_name(doc: &toml_edit::DocumentMut) -> Option<&str> {
297	    doc.get("package").and_then(|p| p.get("name")).and_then(|n| n.as_str())
298	}
