300	/// The metadata crates.io requires that `doc` leaves unset: `description`, and `license` or `license-file`. A field set
301	/// to `{ workspace = true }` is read from `workspace` (the governing `[workspace.package]`), and an empty string counts
302	/// as unset.
303	pub fn missing_crates_io_metadata(
304	    doc: &toml_edit::DocumentMut,
305	    workspace: Option<&toml_edit::DocumentMut>,
306	) -> Vec<&'static str> {
307	    let set = |key: &str| {
308	        let Some(value) = doc.get("package").and_then(|package| package.get(key)) else {
309	            return false;
310	        };
311	        let inherited = value.get("workspace").and_then(toml_edit::Item::as_bool) == Some(true);
312	        let value = if inherited {
313	            workspace
314	                .and_then(|workspace| workspace.get("workspace"))
315	                .and_then(|table| table.get("package"))
316	                .and_then(|package| package.get(key))
317	        } else {
318	            Some(value)
319	        };
320	        value
321	            .and_then(toml_edit::Item::as_str)
322	            .is_some_and(|text| !text.trim().is_empty())
323	    };
324	    let mut missing = Vec::new();
325	    if !set("description") {
326	        missing.push("description");
327	    }
328	    if !set("license") && !set("license-file") {
329	        missing.push("license");
330	    }
331	    missing
332	}
