407	pub(crate) fn workspace_version_from_source(source: &str, path: &Path) -> Result<Option<Version>, ManifestError> {
408	    let clean = source.strip_prefix('\u{FEFF}').unwrap_or(source);
409	    let doc: toml_edit::DocumentMut = clean.parse().map_err(|e: toml_edit::TomlError| ManifestError::Parse {
410	        path: path.to_path_buf(),
411	        format: ManifestFormat::CargoToml,
412	        message: e.to_string(),
413	    })?;
414	    workspace_package_version(&doc, path)
415	}
