435	impl Manifest for CargoToml {
436	    fn persist(&mut self, permit: &ApplyPermit) -> Result<(), ManifestError> {
437	        let text = self.fingerprint.apply(&self.document.to_string());
438	        crate::atomic::atomic_write(&self.absolute, &text, permit).map_err(|e| ManifestError::Write {
439	            path: self.path.clone(),
440	            message: e.to_string(),
441	        })?;
442	        crate::record_persist_call();
443	        Ok(())
444	    }
445	
446	    fn path(&self) -> &Path {
447	        &self.path
448	    }
449	
450	    fn ecosystem(&self) -> Ecosystem {
451	        Ecosystem::Cargo
452	    }
453	
454	    fn is_publishable(&self) -> bool {
455	        let p = match self.document.get("package") {
456	            Some(p) => p,
457	            None => return false,
458	        };
459	        if let Some(pub_val) = p.get("publish") {
460	            if let Some(b) = pub_val.as_bool() {
461	                return b;
462	            }
463	            if let Some(arr) = pub_val.as_array() {
464	                return !arr.is_empty();
465	            }
466	        }
467	        true
468	    }
469	
470	    fn role(&self) -> ManifestRole {
471	        self.role.clone()
472	    }
473	
474	    fn bin_names(&self) -> Result<Vec<String>, ManifestError> {
475	        let Some(package) = cargo_package_name(&self.document) else {
476	            return Ok(Vec::new());
477	        };
478	        let unreadable = |path: &Path, error: std::io::Error| ManifestError::Read {
479	            path: self.path.parent().unwrap_or(Path::new("")).join(path),
480	            message: error.to_string(),
481	        };
482	        let mut names = BTreeSet::new();
483	        if let Some(bins) = self.document.get("bin").and_then(|bin| bin.as_array_of_tables()) {
484	            for target in bins.iter() {
485	                let name = target
486	                    .get("name")
487	                    .and_then(|name| name.as_str())
488	                    .map(str::to_owned)
489	                    .or_else(|| {
490	                        let path = target.get("path").and_then(|path| path.as_str()).map(Path::new)?;
491	                        let stem = path.file_stem()?;
492	                        if stem == "main" {
493	                            path.parent()?.file_name()?.to_str().map(str::to_owned)
494	                        } else {
495	                            stem.to_str().map(str::to_owned)
496	                        }
497	                    })
498	                    .unwrap_or_else(|| package.to_owned());
499	                names.insert(name);
500	            }
501	        }
502	        let autobins = self
503	            .document
504	            .get("package")
505	            .and_then(|item| item.get("autobins"))
506	            .and_then(|item| item.as_bool())
507	            .unwrap_or(true);
508	        if autobins {
509	            let dir = self.absolute.parent().unwrap_or(Path::new("."));
510	            let is_file =
511	                |path: &Path| callisto_model::strict_fs::exists(path).map(|present| present && path.is_file());
512	            if is_file(&dir.join("src/main.rs")).map_err(|error| unreadable(Path::new("src/main.rs"), error))? {
513	                names.insert(package.to_owned());
514	            }
515	            // No `src/bin` is no extra binaries; one that cannot be read is an error.
516	            let entries = match fs::read_dir(dir.join("src/bin")) {
517	                Ok(entries) => entries,
518	                Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(names.into_iter().collect()),
519	                Err(error) => return Err(unreadable(Path::new("src/bin"), error)),
520	            };
521	            for entry in entries {
522	                let path = entry.map_err(|error| unreadable(Path::new("src/bin"), error))?.path();
523	                if path.is_file() && path.extension().is_some_and(|ext| ext == "rs") {
524	                    if let Some(name) = path.file_stem().and_then(|stem| stem.to_str()) {
525	                        names.insert(name.to_owned());
526	                    }
527	                } else if path.is_dir()
528	                    && is_file(&path.join("main.rs")).map_err(|error| unreadable(Path::new("src/bin"), error))?
529	                    && let Some(name) = path.file_name().and_then(|name| name.to_str())
530	                {
531	                    names.insert(name.to_owned());
532	                }
533	            }
534	        }
535	        Ok(names.into_iter().collect())
536	    }
537	
538	    fn napi_lib_name(&self) -> Option<String> {
539	        let lib = self.document.get("lib");
540	        let cdylib = lib
