703	    fn update_dependency_spec(
704	        &mut self,
705	        name: &str,
706	        kind: DepKind,
707	        at: &DepLocator,
708	        new: DepSpec,
709	        permit: &ApplyPermit,
710	    ) -> Result<(), ManifestError> {
711	        let not_found = || ManifestError::DependencyNotFound {
712	            path: self.path.clone(),
713	            name: name.to_string(),
714	            kind,
715	        };
716	        if kind == DepKind::Peer {
717	            return Err(not_found());
718	        }
719	
720	        let (section, target) = match at {
721	            DepLocator::Cargo { section, target, .. } => (section_name(*section), target.as_deref()),
722	            DepLocator::Unspecified => (section_name(kind), None),
723	            _ => return Err(not_found()),
724	        };
725	        let item = dependency_table(&self.document, section, target)
726	            .and_then(|table| table.get(name))
727	            .ok_or_else(not_found)?;
728	
729	        if is_inherited_item(item) {
730	            let root_manifest = self.inheritance.as_ref().ok_or_else(not_found)?.root_manifest.clone();
731	            let root_cargo = self.workspace_root.join(&root_manifest);
732	            if self.absolute == root_cargo {
733	                return Err(ManifestError::InvariantViolation {
734	                    path: self.path.clone(),
735	                    message: format!(
736	                        "dependency `{name}` is workspace-inherited but this manifest IS the workspace root (`{}`); refusing to delegate to avoid overwriting the just-written root manifest with a stale in-memory document",
737	                        root_cargo.display()
738	                    ),
739	                });
740	            }
741	            let mut ws_res = WorkspaceCargoResolver::load_at(&self.workspace_root, &root_manifest)?;
742	            ws_res.write_dependency(name, new, permit)?;
743	            return ws_res.persist(permit);
744	        }
745	
746	        let item = dependency_table_mut(&mut self.document, section, target)
747	            .and_then(|table| table.get_mut(name))
748	            .ok_or_else(not_found)?;
749	        set_dependency_version(item, new.render()).map_err(|()| ManifestError::UnrecognizedDependencyValue {
750	            path: self.path.clone(),
751	            name: name.to_string(),
752	        })
753	    }
