783	/// Every dependency table a manifest can declare: the top-level ones, then the same three
784	/// under each `[target.<cfg>]` key. Owned, so callers can mutate the document while iterating.
785	fn dependency_locations(doc: &toml_edit::DocumentMut) -> Vec<(&'static str, DepKind, Option<String>)> {
786	    let mut locations: Vec<_> = DEPENDENCY_SECTIONS
787	        .iter()
788	        .map(|(section, kind)| (*section, *kind, None))
789	        .collect();
790	    if let Some(targets) = doc.get("target").and_then(|item| item.as_table_like()) {
791	        for (cfg, _) in targets.iter() {
792	            for (section, kind) in DEPENDENCY_SECTIONS {
793	                locations.push((section, kind, Some(cfg.to_string())));
794	            }
795	        }
796	    }
797	    locations
798	}
