841	fn parse_cargo_dep_item(item: &toml_edit::Item, kind: &mut DepKind) -> DepSpec {
842	    if let Some(table) = item.as_inline_table() {
843	        if table.get("optional").and_then(|o| o.as_bool()) == Some(true) {
844	            *kind = DepKind::Optional;
845	        }
846	        if let Some(v_str) = table.get("version").and_then(|v| v.as_str()) {
847	            return parse_cargo_spec_str(v_str);
848	        }
849	    } else if let Some(table) = item.as_table() {
850	        if table.get("optional").and_then(|o| o.as_bool()) == Some(true) {
851	            *kind = DepKind::Optional;
852	        }
853	        if let Some(v_str) = table.get("version").and_then(|v| v.as_str()) {
854	            return parse_cargo_spec_str(v_str);
855	        }
856	    } else if let Some(v_str) = item.as_str() {
857	        return parse_cargo_spec_str(v_str);
858	    }
859	
860	    DepSpec::Opaque(item.to_string().trim().to_string())
861	}
