863	fn parse_cargo_spec_str(s: &str) -> DepSpec {
864	    if crate::common::is_bare_semver(s)
865	        && let Ok(v) = Version::parse(s, VersionGrammar::SemVer)
866	    {
867	        return DepSpec::CargoBare(v);
868	    }
869	    if let Ok(req) = VersionReq::parse(s, Ecosystem::Cargo) {
870	        return DepSpec::Range(req, s.to_string());
871	    }
872	    DepSpec::Opaque(s.to_string())
873	}
