875	pub fn round_trip(spec: &DepSpec, target: &Version) -> Option<DepSpec> {
876	    match spec {
877	        DepSpec::CargoBare(_) => Some(DepSpec::CargoBare(target.clone())),
878	        DepSpec::Range(_, original) => {
879	            if original.contains(',') {
880	                let parts: Vec<&str> = original.split(',').collect();
881	                let mut rewritten_parts = Vec::new();
882	                for part in parts {
883	                    let part_trimmed = part.trim();
884	                    let (prefix, rest) = crate::common::split_single_operator_prefix(part_trimmed)?;
885	                    if prefix.starts_with('>')
886	                        || prefix.starts_with('=')
887	                        || prefix.starts_with('^')
888	                        || prefix.starts_with('~')
889	                    {
890	                        let rendered = format!("{prefix}{}", render_at_precision(target, rest));
891	                        rewritten_parts.push(rendered);
892	                    } else if prefix.starts_with('<') {
893	                        // Upper-bound clauses are never rewritten (the clause text
894	                        // is preserved verbatim), but we must still check whether
895	                        // the target actually falls within it. If it doesn't, the
896	                        // rewrite would silently produce an impossible constraint
897	                        // (e.g. ">=2.1.0, <2.0.0"), so decline with None. If it
898	                        // does, the upper bound clause is passed through unchanged.
899	                        let bound = Version::parse(rest, target.grammar()).ok()?;
900	                        let ordering = target.partial_compare(&bound)?;
901	                        let exceeds_bound = if prefix == "<=" {
902	                            ordering == std::cmp::Ordering::Greater
903	                        } else {
904	                            ordering != std::cmp::Ordering::Less
905	                        };
906	                        if exceeds_bound {
907	                            return None;
908	                        }
909	                        rewritten_parts.push(part_trimmed.to_string());
910	                    } else {
911	                        rewritten_parts.push(part_trimmed.to_string());
912	                    }
913	                }
914	                let rendered = rewritten_parts.join(", ");
915	                let req = VersionReq::parse(&rendered, Ecosystem::Cargo).ok()?;
916	                return Some(DepSpec::Range(req, rendered));
917	            }
918	            let (prefix, rest) = crate::common::split_single_operator_prefix(original)?;
919	            if rest.contains('*') {
920	                return None;
921	            }
922	            let rendered = format!("{prefix}{}", render_at_precision(target, rest));
923	            let req = VersionReq::parse(&rendered, Ecosystem::Cargo).ok()?;
924	            Some(DepSpec::Range(req, rendered))
925	        }
926	        _ => None,
927	    }
928	}
929	
930	fn render_at_precision(target: &Version, original_clause: &str) -> String {
931	    if original_clause.contains('-') || target.is_prerelease() {
932	        return target.render().to_string();
933	    }
934	    let parts: Vec<&str> = original_clause.split('.').collect();
935	    let maj = target.major().unwrap_or(0);
936	    let min = target.minor().unwrap_or(0);
937	    let pat = target.patch().unwrap_or(0);
938	
939	    match parts.len() {
940	        1 => format!("{maj}"),
941	        2 => format!("{maj}.{min}"),
942	        _ => format!("{maj}.{min}.{pat}"),
943	    }
944	}
