1096	    /// Pure in-memory mutation of a `[workspace.dependencies]` entry -- no
1097	    /// disk I/O. See [`Self::write_version`]'s doc for why this no longer
1098	    /// persists internally; callers must call [`Self::persist`] explicitly
1099	    /// afterward.
1100	    pub fn write_dependency(&mut self, name: &str, new: DepSpec, _permit: &ApplyPermit) -> Result<(), ManifestError> {
1101	        let ws = self
1102	            .document
1103	            .get_mut("workspace")
1104	            .and_then(|w| w.as_table_mut())
1105	            .ok_or_else(|| ManifestError::MissingField {
1106	                path: self.root_path.clone(),
1107	                field: "workspace",
1108	            })?;
1109	
1110	        let deps = ws
1111	            .entry("dependencies")
1112	            .or_insert(toml_edit::Item::Table(toml_edit::Table::new()))
1113	            .as_table_like_mut()
1114	            .ok_or_else(|| ManifestError::MissingField {
1115	                path: self.root_path.clone(),
1116	                field: "workspace.dependencies",
1117	            })?;
1118	
1119	        let item = deps.get_mut(name).ok_or_else(|| ManifestError::DependencyNotFound {
1120	            path: self.root_path.clone(),
1121	            name: name.to_string(),
1122	            kind: DepKind::Runtime,
1123	        })?;
1124	
1125	        let new_str = new.render();
1126	        set_dependency_version(item, new_str).map_err(|()| ManifestError::UnrecognizedDependencyValue {
1127	            path: self.root_path.clone(),
1128	            name: name.to_string(),
1129	        })?;
1130	
1131	        Ok(())
1132	    }
1133	
1134	    /// Flushes the in-memory document to disk via
1135	    /// [`crate::atomic::atomic_write`]. Distinct, explicitly-called step --
1136	    /// see [`Self::write_version`]/[`Self::write_dependency`]'s docs --
1137	    /// mirroring the `Manifest` trait's `persist` across `CargoToml`,
1138	    /// `PackageJson`, and `PyprojectToml`.
1139	    pub fn persist(&mut self, permit: &ApplyPermit) -> Result<(), ManifestError> {
1140	        let text = self.document.to_string();
1141	        crate::atomic::atomic_write(&self.absolute_path, &text, permit).map_err(|e| ManifestError::Write {
1142	            path: self.root_path.clone(),
1143	            message: e.to_string(),
1144	        })?;
