1	//! Helpers shared between ecosystem-specific manifest editors (`cargo`, `npm`, `python`).
2	//!
3	//! Only functions verified to be byte-for-byte identical in behavior across
4	//! ecosystems live here. Functions that merely *look* similar but encode
5	//! ecosystem-specific semantics (e.g. `render_at_precision`, which differs
6	//! between Cargo and npm on prerelease/hyphen handling) stay local to their
7	//! respective modules.
8	
9	/// Returns true if `s` looks like a bare `major.minor.patch` semver string
10	/// (as opposed to a range expression like `^1.0.0` or `>=1.0.0`).
11	///
12	/// This is a syntactic heuristic: it does not fully validate the string as
13	/// a semver version, it just checks that it starts with an ASCII digit and
14	/// splits into exactly three dot-separated parts.
15	pub(crate) fn is_bare_semver(s: &str) -> bool {
16	    let chars = s.chars().next();
17	    if !chars.is_some_and(|c| c.is_ascii_digit()) {
18	        return false;
19	    }
20	    let parts: Vec<&str> = s.split('.').collect();
21	    parts.len() == 3
22	}
23	
24	/// Splits a version requirement clause into its leading comparison operator
25	/// (if any) and the remaining version-ish text.
26	///
27	/// Recognized operators: `^`, `~`, `>=`, `>`, `<=`, `<`, `=`. If none match,
28	/// the empty-string prefix is returned along with the trimmed input.
29	pub(crate) fn split_single_operator_prefix(s: &str) -> Option<(&str, &str)> {
30	    let trimmed = s.trim();
31	    for op in ["^", "~", ">=", ">", "<=", "<", "="] {
32	        if let Some(rest) = trimmed.strip_prefix(op) {
33	            return Some((op, rest.trim()));
34	        }
35	    }
36	    Some(("", trimmed))
37	}
38	
39	/// Sets `table[key]` to a scalar string value, preserving the existing
40	/// entry's decor (comments/whitespace) when `table[key]` is already a plain
41	/// value; otherwise inserts a fresh `key = "value"` entry with no decor to
42	/// preserve.
43	///
44	/// Takes `&mut dyn toml_edit::TableLike` rather than a concrete `Table` so
45	/// every call site can share this one implementation regardless of what
46	/// container it holds: a bare `toml_edit::Table` (Cargo's `[package]` /
47	/// `[workspace.package]` tables coerce to `&mut dyn TableLike` directly,
48	/// since `Table: TableLike`) or a `toml_edit::Item` that resolves to a
49	/// table-like value via `Item::as_table_like_mut()` (pyproject.toml's
50	/// `[project]` / `[tool.poetry]` / `[tool.flit.metadata]`, each accessed as
51	/// an `Item`, not a bare `Table`). Previously duplicated as
52	/// `cargo::set_scalar_preserving_decor` and a local closure inside
53	/// `python::PyprojectToml::write_version`.
54	pub(crate) fn set_scalar_preserving_decor(table: &mut dyn toml_edit::TableLike, key: &str, new_value: &str) {
55	    if let Some(item) = table.get_mut(key)
56	        && let Some(val) = item.as_value_mut()
