    fn split_single_operator_prefix_no_operator_returns_empty_prefix() {
        assert_eq!(split_single_operator_prefix("1.2.3"), Some(("", "1.2.3")));
    }

    #[test]
    fn split_single_operator_prefix_trims_whitespace() {
