24	impl CargoToml {
25	    pub fn open(decl: &ManifestDecl, ctx: &OpenContext<'_>) -> Result<Self, ManifestError> {
26	        let rel_path = decl.path.clone();
27	        let abs_path = ctx.workspace_root.join(&rel_path);
28	
29	        let content = fs::read_to_string(&abs_path).map_err(|e| ManifestError::Read {
30	            path: rel_path.clone(),
31	            message: e.to_string(),
32	        })?;
33	
34	        let fingerprint = crate::common::FormatFingerprint::detect(&content);
35	        let clean_content = content.strip_prefix('\u{FEFF}').unwrap_or(&content);
36	
37	        let doc: toml_edit::DocumentMut =
38	            clean_content
39	                .parse()
40	                .map_err(|e: toml_edit::TomlError| ManifestError::Parse {
41	                    path: rel_path.clone(),
42	                    format: ManifestFormat::CargoToml,
43	                    message: e.to_string(),
44	                })?;
45	
46	        let inherited_version = doc
47	            .get("package")
48	            .and_then(|p| p.get("version"))
49	            .and_then(|v| v.get("workspace"))
50	            .and_then(|w| w.as_bool())
51	            == Some(true);
52	
53	        let inherits_dependencies = dependency_locations(&doc).into_iter().any(|(section, _, target)| {
54	            dependency_table(&doc, section, target.as_deref())
55	                .is_some_and(|table| table.iter().any(|(_, item)| is_inherited_item(item)))
56	        });
57	
58	        let inheritance = if inherited_version || inherits_dependencies {
59	            Some(ctx.cargo_inheritance(&rel_path, &doc)?)
60	        } else {
61	            None
62	        };
63	
64	        Ok(CargoToml {
65	            path: rel_path,
66	            absolute: abs_path,
67	            workspace_root: ctx.workspace_root.to_path_buf(),
68	            role: decl.role.clone(),
69	            document: doc,
70	            inherited_version,
71	            inheritance,
72	            fingerprint,
73	        })
74	    }
75	}
