199	/// working tree; see [`WorkspaceReads::enclosing`]. `doc` is the package's own manifest.
200	pub fn enclosing_workspace_manifest(
201	    workspace_root: &Path,
202	    manifest: &Path,
203	    doc: &toml_edit::DocumentMut,
204	) -> Result<Option<PathBuf>, ManifestError> {
