233	/// Every manifest that could be the workspace root of the package at `manifest`: each `Cargo.toml` above its directory,
234	/// and the one its working-tree `package.workspace` names. Fetch these from a commit before asking
235	/// [`WorkspaceReads::enclosing`] about it there.
236	///
237	/// # Errors
238	///
239	/// The package's own manifest cannot be read or parsed.
240	pub fn workspace_manifest_candidates(workspace_root: &Path, manifest: &Path) -> Result<Vec<PathBuf>, ManifestError> {
241	    let dir = manifest.parent().unwrap_or(Path::new(""));
242	    let mut candidates: Vec<PathBuf> = dir
243	        .ancestors()
244	        .skip(1)
245	        .map(|ancestor| ancestor.join("Cargo.toml"))
246	        .collect();
247	    if let Some(text) = read_manifest_text(workspace_root)(manifest)? {
248	        candidates.extend(named_workspace_manifest(manifest, &text)?);
249	    }
250	    candidates.sort();
251	    candidates.dedup();
252	    Ok(candidates)
253	}
