255	/// The workspace manifest that `text`, the content of the package manifest at `manifest`, names with
256	/// `package.workspace`, relative to the workspace root; `None` when it names none or the path leaves the root.
257	///
258	/// # Errors
259	///
260	/// `text` does not parse.
261	pub fn named_workspace_manifest(manifest: &Path, text: &str) -> Result<Option<PathBuf>, ManifestError> {
262	    let dir = manifest.parent().unwrap_or(Path::new(""));
263	    let doc = parse_manifest(manifest, text)?;
264	    Ok(doc
265	        .get("package")
266	        .and_then(|package| package.get("workspace"))
267	        .and_then(toml_edit::Item::as_str)
268	        .and_then(|named| workspace_relative(dir.join(named)).ok())
269	        .map(|root| root.join("Cargo.toml")))
270	}
