334	/// Rewrites a dependency entry's `version` to `new_str`, preserving decor
335	/// across the three shapes Cargo allows for a dependency value: a bare
336	/// version string, an inline table with a `version` key, or a full
337	/// `[dependencies.name]` table with a `version` key. `Err(())` for any
338	/// other shape -- callers map that to their own
339	/// `ManifestError::UnrecognizedDependencyValue` (which needs a `path` this
340	/// function has no access to). Shared by the member-manifest
341	/// ([`CargoToml::update_dependency_spec`]) and workspace-root
342	/// ([`WorkspaceCargoResolver::write_dependency`]) dependency-write paths,
343	/// which were previously two copies of this exact three-shape dance,
344	/// differing only in which path they report on error.
345	fn set_dependency_version(item: &mut toml_edit::Item, new_str: String) -> Result<(), ()> {
346	    if let Some(value) = item.as_value_mut() {
347	        if value.is_str() {
348	            let decor = value.decor().clone();
349	            let mut new_val = toml_edit::Value::from(new_str);
350	            *new_val.decor_mut() = decor;
351	            *value = new_val;
352	        } else if let Some(inline) = value.as_inline_table_mut() {
353	            if let Some(existing_ver) = inline.get_mut("version") {
354	                let decor = existing_ver.decor().clone();
355	                let mut new_val = toml_edit::Value::from(new_str);
356	                *new_val.decor_mut() = decor;
357	                *existing_ver = new_val;
358	            } else {
359	                inline.insert("version", toml_edit::Value::from(new_str));
360	            }
361	        } else {
362	            return Err(());
363	        }
364	    } else if let Some(tbl) = item.as_table_mut() {
365	        if let Some(existing) = tbl.get_mut("version") {
366	            let value = existing.as_value_mut().ok_or(())?;
367	            let decor = value.decor().clone();
368	            let mut new_val = toml_edit::Value::from(new_str);
369	            *new_val.decor_mut() = decor;
370	            *value = new_val;
371	        } else {
372	            tbl.insert("version", toml_edit::value(new_str));
373	        }
374	    } else {
375	        return Err(());
376	    }
377	    Ok(())
378	}
