380	/// [`crate::read_identity`]'s `Cargo.toml` implementation: parses `source`
381	/// and extracts `[package].name` plus a [`crate::VersionSource`] for
382	/// `[package].version` -- `InheritedFromWorkspace` when it's
383	/// `version.workspace = true`, `Literal` when it's a bare string, `None`
384	/// when the field or the whole `[package]` table is absent.
385	pub(crate) fn identity_from_source(source: &str, path: &Path) -> Result<crate::ManifestIdentity, ManifestError> {
386	    let clean = source.strip_prefix('\u{FEFF}').unwrap_or(source);
387	    let doc: toml_edit::DocumentMut = clean.parse().map_err(|e: toml_edit::TomlError| ManifestError::Parse {
388	        path: path.to_path_buf(),
389	        format: ManifestFormat::CargoToml,
390	        message: e.to_string(),
391	    })?;
392	
393	    let name = cargo_package_name(&doc).map(str::to_string);
394	    let version = doc.get("package").and_then(|p| p.get("version")).and_then(|v| {
395	        if let Some(s) = v.as_str() {
396	            Some(crate::VersionSource::Literal(s.to_string()))
397	        } else if v.get("workspace").and_then(|w| w.as_bool()) == Some(true) {
398	            Some(crate::VersionSource::InheritedFromWorkspace)
399	        } else {
400	            None
401	        }
402	    });
403	
404	    Ok(crate::ManifestIdentity { name, version })
405	}
