417	fn workspace_package_version(doc: &toml_edit::DocumentMut, path: &Path) -> Result<Option<Version>, ManifestError> {
418	    let Some(raw) = doc
419	        .get("workspace")
420	        .and_then(|w| w.get("package"))
421	        .and_then(|p| p.get("version"))
422	        .and_then(|v| v.as_str())
423	    else {
424	        return Ok(None);
425	    };
426	    Version::parse(raw, VersionGrammar::SemVer)
427	        .map(Some)
428	        .map_err(|e| ManifestError::Parse {
429	            path: path.to_path_buf(),
430	            format: ManifestFormat::CargoToml,
431	            message: format!("invalid [workspace.package] version: {e}"),
432	        })
433	}
