538	    fn napi_lib_name(&self) -> Option<String> {
539	        let lib = self.document.get("lib");
540	        let cdylib = lib
541	            .and_then(|lib| lib.get("crate-type"))
542	            .and_then(|types| types.as_array())
543	            .is_some_and(|types| types.iter().any(|kind| kind.as_str() == Some("cdylib")));
544	        let napi = self
545	            .document
546	            .get("dependencies")
547	            .and_then(|deps| deps.as_table_like())
548	            .is_some_and(|deps| deps.contains_key("napi"));
549	        if !(cdylib && napi) {
550	            return None;
551	        }
552	        lib.and_then(|lib| lib.get("name"))
553	            .and_then(|name| name.as_str())
554	            .or_else(|| cargo_package_name(&self.document))
555	            .map(|name| name.replace('-', "_"))
556	    }
557	
558	    fn package_name(&self) -> Result<String, ManifestError> {
559	        let name = cargo_package_name(&self.document).ok_or_else(|| ManifestError::MissingField {
560	            path: self.path.clone(),
561	            field: "package.name",
562	        })?;
563	        Ok(name.to_string())
564	    }
565	
566	    fn current_version(&self) -> Result<Version, ManifestError> {
567	        if self.inherited_version {
568	            if let Some(ref inh) = self.inheritance
569	                && let Some(ref v) = inh.version
570	            {
571	                return Ok(v.clone());
572	            }
573	            return Err(ManifestError::WorkspaceInherited {
574	                path: self.path.clone(),
575	                key: "version".to_string(),
576	            });
577	        }
578	
579	        let raw = self
580	            .document
581	            .get("package")
582	            .and_then(|p| p.get("version"))
583	            .and_then(|v| v.as_str())
584	            .ok_or_else(|| ManifestError::MissingField {
585	                path: self.path.clone(),
586	                field: "package.version",
587	            })?;
588	
589	        Version::parse(raw, VersionGrammar::SemVer).map_err(|source| ManifestError::InvalidVersion {
590	            path: self.path.clone(),
591	            raw: raw.to_string(),
592	            source,
593	        })
594	    }
595	
596	    fn write_version(&mut self, v: &Version, _permit: &ApplyPermit) -> Result<(), ManifestError> {
597	        if self.inherited_version {
598	            // The member uses `version.workspace = true` (or `version = { workspace = true }`).
599	            // Routing the bump to [workspace.package] would silently change the version for
600	            // every other workspace member. Instead, write an explicit pinned version directly
601	            // to this member's [package] section, replacing the workspace-inherited entry with
602	            // a standalone string value.
603	            let pkg = self
604	                .document
605	                .get_mut("package")
606	                .and_then(|p| p.as_table_mut())
607	                .ok_or_else(|| ManifestError::MissingField {
608	                    path: self.path.clone(),
609	                    field: "package",
610	                })?;
611	            // The comment above the entry and the one after it belong to the line being replaced. In the dotted form
612	            // (`version.workspace = true`) they hang off `version` and `workspace`, so both are read.
613	            let mut prefix = pkg.key("version").and_then(|key| key.leaf_decor().prefix()).cloned();
614	            let mut suffix = None;
615	            if let Some(item) = pkg.get("version") {
616	                // A value (`version = { workspace = true }`) carries its trailing comment itself; the dotted form is a
617	                // table whose trailing comment is on the `workspace` value inside it.
618	                if let Some(value) = item.as_value() {
619	                    suffix = value.decor().suffix().cloned();
620	                } else if let Some(inner) = item.as_table_like() {
621	                    prefix = prefix.or_else(|| {
622	                        inner
623	                            .get_key_value("workspace")
624	                            .and_then(|(key, _)| key.leaf_decor().prefix().cloned())
625	                    });
626	                    suffix = inner
627	                        .get("workspace")
628	                        .and_then(|value| value.as_value())
629	                        .and_then(|value| value.decor().suffix().cloned());
630	                }
631	            }
632	            pkg.insert("version", toml_edit::value(v.render()));
633	            if let Some(mut key) = pkg.key_mut("version")
634	                && let Some(prefix) = prefix
635	            {
636	                key.leaf_decor_mut().set_prefix(prefix);
637	            }
638	            if let (Some(value), Some(suffix)) = (pkg.get_mut("version").and_then(|item| item.as_value_mut()), suffix) {
639	                value.decor_mut().set_suffix(suffix);
640	            }
641	            self.inherited_version = false;
642	            return Ok(());
643	        }
644	
645	        let pkg = self
646	            .document
647	            .get_mut("package")
648	            .and_then(|p| p.as_table_mut())
649	            .ok_or_else(|| ManifestError::MissingField {
650	                path: self.path.clone(),
651	                field: "package",
652	            })?;
653	
654	        crate::common::set_scalar_preserving_decor(pkg, "version", v.render());
655	        Ok(())
656	    }
