662	    fn iter_dependencies(&self) -> Box<dyn Iterator<Item = DependencyEntry> + '_> {
663	        let mut entries = Vec::new();
664	
665	        for (section_name, section_kind, target) in dependency_locations(&self.document) {
666	            if let Some(table) = dependency_table(&self.document, section_name, target.as_deref()) {
667	                for (name, item) in table.iter() {
668	                    let is_inherited = is_inherited_item(item);
669	                    let mut kind = section_kind;
670	                    let local_spec = parse_cargo_dep_item(item, &mut kind);
671	                    let inherited_dep = self.inheritance.as_ref().and_then(|inh| inh.inherited(name));
672	                    let package_name = if is_inherited {
673	                        inherited_dep.map(|dep| dep.package_name).unwrap_or(name)
674	                    } else {
675	                        cargo_dependency_package_name(name, item)
676	                    };
677	
678	                    let spec = if is_inherited {
679	                        if let Some(inherited_dep) = inherited_dep {
680	                            inherited_dep.spec.clone()
681	                        } else {
682	                            DepSpec::Opaque("workspace = true (unresolved)".to_string())
683	                        }
684	                    } else {
685	                        local_spec
686	                    };
687	
688	                    entries.push(DependencyEntry {
689	                        name: name.to_string(),
690	                        package_name: package_name.to_string(),
691	                        kind,
692	                        spec,
693	                        inherited: is_inherited,
694	                        locator: DepLocator::cargo(section_kind, target.clone()),
695	                    });
696	                }
697	            }
698	        }
699	
700	        Box::new(entries.into_iter())
701	    }
