768	const DEPENDENCY_SECTIONS: [(&str, DepKind); 3] = [
769	    ("dependencies", DepKind::Runtime),
770	    ("dev-dependencies", DepKind::Dev),
771	    ("build-dependencies", DepKind::Build),
772	];
