774	/// The Cargo section a dependency kind is declared in; optional dependencies sit beside runtime ones.
775	fn section_name(kind: DepKind) -> &'static str {
776	    match kind {
777	        DepKind::Dev => "dev-dependencies",
778	        DepKind::Build => "build-dependencies",
779	        _ => "dependencies",
780	    }
781	}
