800	fn dependency_table<'a>(
801	    doc: &'a toml_edit::DocumentMut,
802	    section: &str,
803	    target: Option<&str>,
804	) -> Option<&'a dyn toml_edit::TableLike> {
805	    let parent = match target {
806	        Some(cfg) => doc.get("target")?.get(cfg)?,
807	        None => doc.as_item(),
808	    };
809	    parent.get(section)?.as_table_like()
