825	fn is_inherited_item(item: &toml_edit::Item) -> bool {
826	    item.as_inline_table()
827	        .and_then(|table| table.get("workspace"))
828	        .and_then(|workspace| workspace.as_bool())
829	        == Some(true)
830	        || item
831	            .as_table()
832	            .and_then(|table| table.get("workspace"))
833	            .and_then(|workspace| workspace.as_bool())
834	            == Some(true)
