67	/// A file's line-ending style: bare LF, or CRLF (common on Windows / repos
68	/// with `core.autocrlf=true`).
69	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
70	pub(crate) enum LineEnding {
71	    Lf,
72	    CrLf,
73	}
74	
75	/// Byte-level formatting facts that a CST-preserving editor must detect on
76	/// open and reapply verbatim on persist, since `toml_edit`/`serde_json`
77	/// re-serialization always produces bare-LF text with no BOM regardless of
78	/// what was originally on disk: whether the file opened with a UTF-8 BOM,
79	/// and its line-ending style.
80	///
81	/// Previously reimplemented independently -- byte-for-byte identically --
82	/// as a private `has_bom`/`line_ending` pair (plus a duplicate local
83	/// `LineEnding` enum) in both `npm::PackageJson` and
84	/// `python::PyprojectToml`, and entirely absent from `cargo::CargoToml`
85	/// (F4: a CRLF `Cargo.toml` was silently rewritten to LF on any write).
86	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
87	pub(crate) struct FormatFingerprint {
88	    pub(crate) has_bom: bool,
89	    pub(crate) line_ending: LineEnding,
90	}
91	
92	impl FormatFingerprint {
93	    /// Detects BOM and line-ending style from `content`, the raw file text
94	    /// exactly as read from disk (BOM still present, if any -- this does
95	    /// its own BOM-stripping internally before checking for `"\r\n"`, so
96	    /// callers need not pre-strip).
97	    pub(crate) fn detect(content: &str) -> Self {
98	        let has_bom = content.starts_with('\u{FEFF}');
99	        let clean = content.strip_prefix('\u{FEFF}').unwrap_or(content);
100	        let line_ending = if clean.contains("\r\n") {
101	            LineEnding::CrLf
102	        } else {
103	            LineEnding::Lf
104	        };
105	        FormatFingerprint { has_bom, line_ending }
106	    }
107	
108	    /// Reapplies this fingerprint to `rendered` -- a freshly-serialized
109	    /// document body with bare-LF line endings and no BOM -- producing the
110	    /// exact text that should be written to disk.
111	    pub(crate) fn apply(&self, rendered: &str) -> String {
112	        let mut out = if self.line_ending == LineEnding::CrLf {
113	            rendered.replace("\r\n", "\n").replace('\n', "\r\n")
114	        } else {
115	            rendered.to_string()
116	        };
117	        if self.has_bom {
118	            out = format!("\u{FEFF}{out}");
119	        }
120	        out
121	    }
122	}
