93	            if req.matches(new)? {
94	                Ok(Coverage::Covers)
95	            } else {
96	                Ok(Coverage::DoesNotCover)
97	            }
98	        }
99	        DepSpec::Workspace(_) => Ok(Coverage::Covers),
100	        DepSpec::WorkspaceProtocol(workspace) => workspace.coverage(new),
101	        DepSpec::Catalog(_) | DepSpec::Opaque(_) => Ok(Coverage::Unknown),
102	    }
103	}
104	
105	pub(crate) fn caret_covers(cur: &Version, new: &Version) -> Result<bool, GrammarMismatch> {
106	    let cmp = Version::compare(new, cur)?;
107	    if cmp.is_lt() {
108	        return Ok(false);
109	    }
110	    // A caret requirement always matches the version it names, pre-release or not.
111	    if new == cur {
112	        return Ok(true);
113	    }
114	    // Pre-release versions are never covered by a caret range: ^1.2.3 must not
115	    // satisfy 1.9.0-alpha.1 even though 1.9.0-alpha.1 > 1.2.3 and they share
116	    // the same major. Caret ranges cover stable releases within the allowed
117	    // major/minor bounds only; a pre-release of an in-range stable version is
118	    // not itself a stable release and must not be treated as covered.
119	    if new.is_prerelease() {
120	        return Ok(false);
121	    }
122	    let cur_maj = cur.major().unwrap_or(0);
123	    let cur_min = cur.minor().unwrap_or(0);
124	    let new_maj = new.major().unwrap_or(0);
125	    let new_min = new.minor().unwrap_or(0);
126	
127	    if cur_maj > 0 {
128	        Ok(new_maj == cur_maj)
129	    } else if cur_min > 0 {
130	        Ok(new_maj == 0 && new_min == cur_min)
131	    } else {
132	        Ok(new == cur)
133	    }
134	}
