170	pub(crate) fn dependency_rewrite_key(edge: &DepEdge) -> RewriteKey {
171	    RewriteKey {
172	        target: if edge.inherited {
173	            DepWriteTarget::CargoWorkspaceDependency {
174	                root_manifest: edge.from_manifest.clone(),
175	            }
176	        } else {
177	            DepWriteTarget::Manifest(edge.from_manifest.clone())
178	        },
179	        name: edge.name.clone(),
180	        kind: if edge.inherited { None } else { Some(edge.kind) },
181	        // An inherited declaration is rewritten once, in the workspace root, whichever member table names it.
182	        locator: if edge.inherited {
183	            DepLocator::default()
184	        } else {
185	            edge.locator.clone()
186	        },
187	    }
188	}
