190	/// Propagates `input.seed`'s severities outward to dependents until no
191	/// target version changes, or `convergence_bound`'s iteration cap is
192	/// exceeded ([`GraphError::CascadeNotConverged`]) -- turns a would-be
193	/// infinite loop into a reportable bug, bound derived from package count.
194	///
195	/// One pass: pop a package, compute its bumped target, walk every
196	/// dependent edge, apply [`cascade_action`] to decide if that dependent's
197	/// severity/target changes and gets re-queued.
198	///
199	/// A genuine cross-grammar coverage failure (`coverage`'s `Err`, e.g.
200	/// SemVer target vs. PEP440 spec) aborts the whole cascade with
201	/// `Err(GraphError::GrammarMismatch)`. Soft instead: `Catalog`/`Opaque`
202	/// specs never have coverage tested (`coverage` returns `Unknown`
203	/// unconditionally), so they can't block anything -- `Catalog` gets
204	/// [`DiagnosticCode::CatalogSpecNotRewritten`], `Opaque` gets no
205	/// diagnostic. [`DiagnosticCode::RangeNotRoundTrippable`]'s real trigger
206	/// is a different step: [`rewrite_spec`], when a mechanical range rewrite
207	/// (not a coverage test) fails on an otherwise-known-coverage spec.
208	pub fn solve_cascade<D: DependencyResolver>(input: CascadeInput<'_, D>) -> Result<CascadeOutcome, GraphError> {
209	    let mut out = CascadeOutcome {
210	        severities: input.seed.clone(),
211	        reasons: input.reasons.clone(),
212	        ..Default::default()
213	    };
214	
215	    for (id, &sev) in input.seed {
216	        let t = bump_target(id, sev, &input)?;
217	        out.targets.insert(id.clone(), t);
218	    }
219	
220	    let mut worklist: BTreeSet<PackageId> = out.targets.keys().cloned().collect();
221	    let mut iterations = 0;
222	    let bound = convergence_bound(input.graph.packages().count());
223	    // Edges already run through rewrite_spec, so the floor-raise pass below doesn't re-diagnose them.
224	    let mut rewrite_attempted: BTreeSet<RewriteKey> = BTreeSet::new();
225	
226	    let mut changed = true;
227	    while changed {
228	        changed = false;
229	
230	        while let Some(pkg) = worklist.pop_first() {
231	            iterations += 1;
232	            if iterations > bound {
233	                return Err(GraphError::CascadeNotConverged { iterations });
234	            }
235	
236	            let new_version = out.targets[&pkg].clone();
237	            let src_sev = out.severities[&pkg];
238	
239	            let dependents: Vec<DepEdge> = input.graph.dependents_of(&pkg).cloned().collect();
240	            for edge in dependents {
241	                let cov = coverage(&edge.spec, &new_version).map_err(|source| GraphError::GrammarMismatch {
242	                    from: edge.from.clone(),
243	                    to: edge.to.clone(),
244	                    source,
245	                })?;
246	
247	                let d = cascade_action(edge.kind, cov, src_sev, input.cfg);
248	
249	                if d.unknown_coverage && !matches!(edge.spec, DepSpec::Opaque(_)) {
250	                    let code = match edge.spec {
251	                        DepSpec::Catalog(_) => DiagnosticCode::CatalogSpecNotRewritten,
252	                        _ => DiagnosticCode::RangeNotRoundTrippable,
253	                    };
254	                    out.diagnostics.push(Diagnostic {
255	                        code,
256	                        severity: DiagnosticSeverity::Warning,
257	                        message: format!(
258	                            "spec `{}` for `{}` could not be tested for coverage",
259	                            edge.spec.render(),
260	                            edge.to.display_name()
261	                        ),
262	                        package: Some(edge.from.clone()),
263	                        path: Some(edge.from_manifest.clone()),
264	                        governed_by: Some(ConfigKey::CASCADE_PRESERVE_NPM_RANGES),
265	                        escalated_by: None,
266	                    });
267	                }
268	
269	                if d.rewrite {
270	                    match rewrite_edge(&edge, &new_version, input.cfg)? {
271	                        RewriteOutcome::Rewritten(to_spec) => {
272	                            let key = dependency_rewrite_key(&edge);
273	                            rewrite_attempted.insert(key.clone());
274	                            out.rewrites.insert(
275	                                key.clone(),
276	                                SpecRewrite {
277	                                    key,
278	                                    dependency: edge.to.clone(),
279	                                    from: edge.spec.clone(),
280	                                    to: to_spec,
281	                                },
282	                            );
283	                        }
284	                        RewriteOutcome::LeftAlone(dg) => {
285	                            rewrite_attempted.insert(dependency_rewrite_key(&edge));
286	                            out.diagnostics.push(dg);
287	                        }
288	                    }
289	                }
290	
291	                let cur_sev = out.severities.get(&edge.from).copied().unwrap_or(Severity::None);
292	                if d.severity > cur_sev {
293	                    raise(
294	                        &edge.from,
295	                        d.severity,
296	                        &d,
297	                        &pkg,
298	                        &edge,
299	                        &new_version,
300	                        &mut out,
301	                        input.groups,
302	                        &mut worklist,
303	                        &input,
304	                    )?;
305	                }
306	            }
307	        }
308	
309	        // Linked group release severity propagation
310	        for g in input.groups.linked.values() {
311	            let max_sev = g.max_severity(&out.severities);
312	            if max_sev == Severity::None {
313	                continue;
314	            }
315	
316	            // A member absent from `input.base` was removed from the
317	            // workspace but is still listed in the group config. Skip it
318	            // rather than let `bump_target` below hit `MissingField` --
319	            // mirrors the guard `aggregate::union_fixed`/`union_linked`
320	            // already apply before cascade convergence ever starts.
321	            let mut live_members = Vec::new();
322	            for id in g.package_members() {
323	                if !input.base.contains_key(id) {
324	                    out.diagnostics.push(Diagnostic {
325	                        code: DiagnosticCode::UnknownPackage,
326	                        severity: DiagnosticSeverity::Warning,
327	                        message: format!(
328	                            "Linked group `{}` references package `{}` which is not in the \
329	                             workspace; the stale group member is skipped. Remove it from \
330	                             callisto.toml to silence this warning.",
331	                            g.name,
332	                            id.display_name()
333	                        ),
334	                        package: Some(id.clone()),
335	                        path: None,
336	                        governed_by: Some(ConfigKey::LINKED_GROUP),
337	                        escalated_by: None,
338	                    });
339	                    continue;
340	                }
341	                live_members.push(id.clone());
342	                let cur_sev = out.severities.get(id).copied().unwrap_or(Severity::None);
343	                if max_sev > cur_sev {
344	                    out.severities.insert(id.clone(), max_sev);
345	                }
346	            }
347	
348	            let mut winner: Option<Version> = None;
349	            for id in &live_members {
350	                let candidate = bump_target(id, max_sev, &input)?;
351	                winner = Some(match winner {
352	                    None => candidate,
353	                    Some(best) => {
354	                        let cmp = Version::compare(&candidate, &best).map_err(|_grammar_mismatch| {
355	                            GraphError::GroupGrammarMismatch {
356	                                group: g.name.clone(),
357	                                members: live_members
358	                                    .iter()
359	                                    .filter_map(|m| out.targets.get(m).map(|v| (m.clone(), v.clone())))
360	                                    .collect(),
361	                            }
362	                        })?;
363	                        if cmp.is_gt() {
364	                            candidate
365	                        } else {
366	                            best
367	                        }
368	                    }
369	                });
370	            }
371	            let Some(winner) = winner else { continue };
372	
373	            for id in live_members {
374	                if out.targets.get(&id) != Some(&winner) {
375	                    out.targets.insert(id.clone(), winner.clone());
376	                    out.reasons
377	                        .insert(id.clone(), BumpReason::LinkedGroupUnion { group: g.name.clone() });
378	                    worklist.insert(id.clone());
379	                    changed = true;
380	                }
381	            }
382	        }
383	
384	        // Fixed group convergence -- mirrors the Linked-group block
385	        // above but computes each group's shared target via
386	        // fixed_group_target instead of taking the max of independently
387	        // bumped per-member candidates.
388	        for g in input.groups.fixed.values() {
389	            let max_sev = g.max_severity(&out.severities);
390	            if max_sev == Severity::None {
391	                continue;
392	            }
393	
394	            // A member absent from `input.base` was removed from the
395	            // workspace but is still listed in the group config. Skip it
396	            // rather than let it flow into `out.severities`/`out.targets`,
397	            // which `plan_version`'s `pkg_map.get(id).copied().unwrap()`
398	            // (built only from live graph packages) would later panic on --
399	            // mirrors the guard `aggregate::union_fixed`/`union_linked` and
400	            // the Linked-group block above already apply.
401	            let mut live_members = Vec::new();
402	            for id in g.package_members() {
403	                if !input.base.contains_key(id) {
404	                    out.diagnostics.push(Diagnostic {
405	                        code: DiagnosticCode::UnknownPackage,
406	                        severity: DiagnosticSeverity::Warning,
407	                        message: format!(
408	                            "Fixed group `{}` references package `{}` which is not in the \
409	                             workspace; the stale group member is skipped. Remove it from \
410	                             callisto.toml to silence this warning.",
411	                            g.name,
412	                            id.display_name()
413	                        ),
414	                        package: Some(id.clone()),
415	                        path: None,
416	                        governed_by: Some(ConfigKey::FIXED_GROUP),
417	                        escalated_by: None,
418	                    });
419	                    continue;
420	                }
421	                live_members.push(id.clone());
422	                let cur_sev = out.severities.get(id).copied().unwrap_or(Severity::None);
423	                if max_sev > cur_sev {
424	                    out.severities.insert(id.clone(), max_sev);
425	                }
426	            }
427	
428	            let winner =
429	                crate::groups::fixed_group_target(&g.name, &live_members, input.base, max_sev, input.tags, input.pre)?;
430	
431	            for id in live_members {
432	                if out.targets.get(&id) != Some(&winner) {
433	                    out.targets.insert(id.clone(), winner.clone());
434	                    out.reasons
435	                        .insert(id.clone(), BumpReason::FixedGroupUnion { group: g.name.clone() });
436	                    worklist.insert(id.clone());
437	                    changed = true;
438	                }
439	            }
440	        }
441	    }
442	
443	    // A releasing package's floor on a co-released dependency is always raised, even when the old spec still covers it.
444	    for pkg in out.severities.keys().cloned().collect::<Vec<_>>() {
445	        let deps: Vec<DepEdge> = input.graph.dependencies_of(&pkg).cloned().collect();
446	        for edge in deps {
447	            if edge.kind == DepKind::Dev {
448	                continue;
449	            }
450	            if matches!(
451	                edge.spec,
452	                DepSpec::Workspace(_) | DepSpec::Catalog(_) | DepSpec::Opaque(_)
453	            ) {
454	                continue;
455	            }
456	            let Some(new_version) = out.targets.get(&edge.to).cloned() else {
457	                continue;
458	            };
459	            if matches!(edge.spec, DepSpec::WorkspaceProtocol(_))
460	                && coverage(&edge.spec, &new_version).map_err(|source| GraphError::GrammarMismatch {
461	                    from: edge.from.clone(),
462	                    to: edge.to.clone(),
463	                    source,
464	                })? != Coverage::DoesNotCover
465	            {
466	                continue;
467	            }
468	
469	            let key = dependency_rewrite_key(&edge);
470	            if rewrite_attempted.contains(&key) {
471	                continue;
472	            }
473	
474	            // A floor that cannot be raised (`*`, a bare Python requirement, `||` sets) is harmless while it covers.
475	            if matches!(coverage(&edge.spec, &new_version), Ok(Coverage::Covers))
476	                && matches!(
477	                    rewrite_spec(
478	                        &edge.spec,
479	                        &new_version,
480	                        manifest_ecosystem(&edge.from_manifest),
481	                        input.cfg
482	                    ),
483	                    RewriteOutcome::LeftAlone(_)
484	                )
485	            {
486	                continue;
487	            }
488	
489	            match rewrite_edge(&edge, &new_version, input.cfg)? {
490	                RewriteOutcome::Rewritten(to_spec) => {
491	                    out.rewrites.entry(key.clone()).or_insert_with(|| SpecRewrite {
492	                        key,
493	                        dependency: edge.to.clone(),
494	                        from: edge.spec.clone(),
495	                        to: to_spec,
496	                    });
497	                }
498	                RewriteOutcome::LeftAlone(dg) => {
499	                    out.diagnostics.push(dg);
500	                }
501	            }
502	        }
503	    }
504	
505	    out.iterations = iterations;
506	    Ok(out)
507	}
508	
509	fn bump_target<D: DependencyResolver>(
510	    id: &PackageId,
511	    sev: Severity,
512	    input: &CascadeInput<'_, D>,
513	) -> Result<Version, GraphError> {
514	    let base = input.base.get(id).cloned().ok_or_else(|| {
515	        GraphError::Manifest(callisto_model::ManifestError::MissingField {
516	            path: PathBuf::from(id.name()),
517	            field: "version",
518	        })
519	    })?;
520	
521	    // PreMode::Exit falls through to a plain `versioning.bump`, which strips a matching pre-release tag directly.
522	    crate::groups::versioned_bump(id, &base, sev, input.pre)
523	}
524	
525	#[allow(clippy::too_many_arguments)]
526	fn raise<D: DependencyResolver>(
527	    pkg: &PackageId,
528	    sev: Severity,
529	    decision: &CascadeDecision,
530	    via: &PackageId,
531	    edge: &DepEdge,
532	    dependency_to: &Version,
533	    out: &mut CascadeOutcome,
534	    groups: &GroupTable,
535	    worklist: &mut BTreeSet<PackageId>,
536	    input: &CascadeInput<'_, D>,
537	) -> Result<bool, GraphError> {
538	    let cur_sev = out.severities.get(pkg).copied().unwrap_or(Severity::None);
539	    if sev <= cur_sev {
540	        return Ok(false);
541	    }
542	
543	    out.severities.insert(pkg.clone(), sev);
544	
545	    let new_reason = if decision.escalated {
546	        BumpReason::PeerEscalation {
547	            via: via.clone(),
548	            spec: edge.spec.render(),
549	        }
550	    } else {
551	        BumpReason::Cascade {
552	            via: via.clone(),
553	            dep_kind: edge.kind,
554	            spec: edge.spec.render(),
555	            dependency_to: dependency_to.clone(),
556	        }
557	    };
558	    out.reasons.insert(pkg.clone(), new_reason);
559	
560	    if let Some(ref gov) = decision.governed_by {
561	        out.governed_by.insert(pkg.clone(), gov.clone());
562	    }
563	
564	    let new_t = bump_target(pkg, sev, input)?;
565	    out.targets.insert(pkg.clone(), new_t);
566	    worklist.insert(pkg.clone());
567	
568	    for sib in groups.fixed_siblings(pkg) {
569	        let sib_sev = out.severities.get(sib).copied().unwrap_or(Severity::None);
570	        if sev > sib_sev {
571	            out.severities.insert(sib.clone(), sev);
572	            out.reasons.insert(
573	                sib.clone(),
574	                BumpReason::FixedGroupUnion {
575	                    group: groups
576	                        .fixed_group_of(pkg)
577	                        .expect("a fixed-group sibling implies the package has a fixed group")
578	                        .name
579	                        .clone(),
580	                },
581	            );
582	            let sib_t = bump_target(sib, sev, input)?;
583	            out.targets.insert(sib.clone(), sib_t);
584	            worklist.insert(sib.clone());
585	        }
586	    }
587	
588	    Ok(true)
589	}
