622	/// Rewrites one dependency edge toward `new`. A range a consumer's published manifest would keep excluding `new`
623	/// stops the run; only a dev dependency, which consumers never install, is left alone with a warning.
624	pub(crate) fn rewrite_edge(edge: &DepEdge, new: &Version, cfg: &CascadeConfig) -> Result<RewriteOutcome, GraphError> {
625	    let eco = manifest_ecosystem(&edge.from_manifest);
626	    match rewrite_spec(&edge.spec, new, eco, cfg) {
627	        RewriteOutcome::LeftAlone(_) if edge.kind != DepKind::Dev => Err(GraphError::UnrewritableRange {
628	            dependent: edge.from.display_name(),
629	            dependency: edge.to.display_name(),
630	            spec: edge.spec.render(),
631	            version: new.render().to_string(),
632	            manifest: edge.from_manifest.display().to_string(),
633	        }),
634	        outcome => Ok(outcome),
635	    }
636	}
637	
638	pub fn rewrite_spec(original: &DepSpec, new: &Version, eco: Ecosystem, cfg: &CascadeConfig) -> RewriteOutcome {
639	    if !cfg.preserve_npm_ranges && eco == Ecosystem::Npm && !matches!(original, DepSpec::WorkspaceProtocol(_)) {
640	        return RewriteOutcome::Rewritten(DepSpec::Exact(new.clone()));
641	    }
642	
643	    // A rewrite that still excludes `new` is no rewrite: the dependent would publish a range its dependency cannot meet.
644	    match callisto_manifests::round_trip(eco, original, new)
645	        .filter(|rewritten| matches!(coverage(rewritten, new), Ok(Coverage::Covers | Coverage::Unknown)))
646	    {
647	        Some(rewritten) => RewriteOutcome::Rewritten(rewritten),
648	        _ => RewriteOutcome::LeftAlone(Diagnostic {
649	            code: DiagnosticCode::RangeNotRoundTrippable,
650	            severity: DiagnosticSeverity::Warning,
651	            message: format!(
652	                "spec `{}` could not be round-tripped toward version `{}`",
653	                original.render(),
654	                new.render()
655	            ),
656	            package: None,
657	            path: None,
658	            governed_by: Some(ConfigKey::CASCADE_PRESERVE_NPM_RANGES),
659	            escalated_by: None,
660	        }),
661	    }
662	}
